import React from 'react';

// This component receives the item data and the handler functions from its parent
const CartItem = ({ item, onUpdateQuantity, onRemoveItem }) => {
    // Handle potential missing data
    const itemName = item.name || item.productName || 'Unknown Product';
    const itemPrice = item.lineTotal || (item.price * item.quantity) || 0;
    const itemQuantity = item.quantity || 1;
    
    return (
        <div className="cart-item">
            {/* Use placeholder image - you can update this to use actual product images */}
            <img 
                src={item.imageUrl || `https://via.placeholder.com/80?text=${itemName.replace(/\s+/g, '+')}`} 
                alt={itemName} 
                className="cart-item-image" 
            />
            
            <div className="cart-item-details">
                <h4>{itemName}</h4>
                <p>{item.description || 'Product details'}</p>
                {item.price && <p>Unit Price: Rs. {item.price.toFixed(2)}</p>}
            </div>

            <div className="quantity-controls">
                <button 
                    className="quantity-btn"
                    onClick={() => onUpdateQuantity(item.productId, Math.max(0, itemQuantity - 1))}
                    disabled={itemQuantity <= 1}
                    style={{
                        opacity: itemQuantity <= 1 ? 0.5 : 1,
                        cursor: itemQuantity <= 1 ? 'not-allowed' : 'pointer'
                    }}
                >
                    -
                </button>
                <span className="quantity-display">{itemQuantity}</span>
                <button 
                    className="quantity-btn"
                    onClick={() => onUpdateQuantity(item.productId, itemQuantity + 1)}
                >
                    +
                </button>
            </div>

            <span className="cart-item-price">Rs. {itemPrice.toFixed(2)}</span>

            <button 
                className="remove-item-btn" 
                onClick={() => onRemoveItem(item.productId)}
                title="Remove item from cart"
            >
                &times; {/* This is a multiplication sign 'X' */}
            </button>
        </div>
    );
};

export default CartItem;
